"use client";
import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { useFlowGroup } from "@/lib/cojeev-motion/use-flow";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Label, type LabelProps } from "@/components/ui/label";
import {
  controlRadiusStyle,
  type ControlAppearanceProps,
} from "@/lib/cojeev/control-appearance";
const FieldContext = React.createContext<{
  id: string;
  invalid: boolean;
  descriptions: string[];
  registerDescription: (id: string) => () => void;
} | null>(null);
const fieldVariants = cva(
  "v-field grid gap-[8px] [border:0] bg-transparent [box-shadow:none]",
  {
    variants: { variant: { default: "", invalid: "-invalid" } },
    defaultVariants: { variant: "default" },
  },
);
export type FieldProps = React.ComponentProps<"div"> &
  VariantProps<typeof fieldVariants> &
  ControlAppearanceProps & {
    invalid?: boolean;
    controlId?: string;
    /** Place supporting copy beside the control, or collect it in one well. */
    layout?: "stacked" | "inline" | "integrated";
  };
export function Field({
  radius,
  appearance,
  style,
  className,
  variant,
  invalid = variant === "invalid",
  controlId,
  layout,
  children,
  ...props
}: FieldProps) {
  const generatedId = React.useId();
  const [descriptions, setDescriptions] = React.useState<string[]>([]);
  const registerDescription = React.useCallback((id: string) => {
    setDescriptions((current) =>
      current.includes(id) ? current : [...current, id],
    );
    return () =>
      setDescriptions((current) => current.filter((value) => value !== id));
  }, []);
  return (
    <FieldContext.Provider
      value={{
        id: controlId ?? generatedId,
        invalid,
        descriptions,
        registerDescription,
      }}
    >
      <div
        data-slot="field"
        data-appearance={appearance}
        data-layout={layout}
        style={{ ...style, ...controlRadiusStyle(radius) }}
        data-part="root"
        data-state={invalid ? "error" : "rest"}
        className={cn(
          fieldVariants({ variant: invalid ? "invalid" : variant }),
          className,
        )}
        {...props}
      >
        {children}
      </div>
    </FieldContext.Provider>
  );
}
export type FieldLabelProps = LabelProps;
export function FieldLabel(props: FieldLabelProps) {
  const field = React.useContext(FieldContext);
  return (
    <Label
      data-slot="field-label"
      data-part="label"
      htmlFor={field?.id}
      {...props}
    />
  );
}
export type FieldControlProps = React.ComponentProps<typeof Slot>;
export function FieldControl({ children, ...props }: FieldControlProps) {
  const field = React.useContext(FieldContext);
  return (
    <Slot
      data-part="input"
      id={field?.id}
      aria-invalid={field?.invalid || undefined}
      aria-describedby={
        field?.descriptions.length ? field.descriptions.join(" ") : undefined
      }
      {...props}
    >
      {children}
    </Slot>
  );
}
export type FieldDescriptionProps = React.ComponentProps<"p">;
export function FieldDescription({
  className,
  id: suppliedId,
  ...props
}: FieldDescriptionProps) {
  const field = React.useContext(FieldContext);
  const generatedId = React.useId();
  const id = suppliedId ?? `${field?.id ?? "field"}-message-${generatedId}`;
  const register = field?.registerDescription;
  React.useLayoutEffect(() => register?.(id), [register, id]);
  return (
    <p
      data-slot="field-description"
      data-part="message"
      id={id}
      className={cn(
        "v-help min-h-[1.3em] text-[length:var(--fs-meta)] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type FieldErrorProps = FieldDescriptionProps & {
  errors?: Array<{ message?: string } | undefined>;
};
export function FieldError({ errors, children, ...props }: FieldErrorProps) {
  return (
    <FieldDescription role="alert" {...props}>
      {children ??
        [
          ...new Set(errors?.map((error) => error?.message).filter(Boolean)),
        ].join(" ")}
    </FieldDescription>
  );
}
export type FieldSetProps = React.ComponentProps<"fieldset">;
export function FieldSet({ ref, className, ...props }: FieldSetProps) {
  const flowRef = useFlowGroup<HTMLFieldSetElement>(ref);
  return (
    <fieldset
      ref={flowRef}
      data-flow-fields=""
      data-slot="field-set"
      className={cn("grid min-w-0 gap-[var(--s-5)] [border:0] p-0", className)}
      {...props}
    />
  );
}
export type FieldLegendProps = React.ComponentProps<"legend">;
export function FieldLegend({ className, ...props }: FieldLegendProps) {
  return (
    <legend
      data-slot="field-legend"
      className={cn(
        "v-label text-[length:var(--fs-lead)] font-semibold",
        className,
      )}
      {...props}
    />
  );
}
export type FieldGroupProps = React.ComponentProps<"div"> & {
  asChild?: boolean;
};
export function FieldGroup({
  ref,
  asChild,
  className,
  ...props
}: FieldGroupProps) {
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  const Comp = asChild ? Slot : "div";
  return (
    <Comp
      ref={flowRef}
      data-flow-fields=""
      data-slot="field-group"
      className={cn(!asChild && "grid gap-[var(--s-5)]", className)}
      {...props}
    />
  );
}
export { fieldVariants };

@layer cojeev-states {
[data-slot="field"].-invalid .v-help {
  color: var(--v-danger-ink);
}
[data-slot="field"]:has(:disabled) .v-label {
  color: var(--v-disabled-ink);
}
[data-slot="field"].-invalid :is(.v-input, .v-textarea) {
  box-shadow: inset 0 0 0 2px var(--v-danger);
  background: color-mix(in oklab, var(--v-danger) 6%, var(--input));
}
[data-slot="field"].-ok .v-input {
  box-shadow: inset 0 0 0 2px var(--v-olive);
}
[data-slot="field"].-ok .v-help {
  color: var(--v-olive-ink);
}
:root[data-mode="dark"] [data-slot="field"].-invalid .v-input {
  background: color-mix(in oklab, var(--v-danger) 14%, var(--v-canvas));
}
[data-slot="field"]:is(.-error, [data-invalid]) .v-input {
  box-shadow: inset 0 0 0 1.5px var(--v-danger-fill);
  background: var(--v-danger-soft);
}
[data-slot="field"]:is(.-error, [data-invalid]) .v-input:focus-within {
  box-shadow: inset 0 0 0 2px var(--v-danger-fill);
}

[data-slot="field"].-invalid .v-input { border: 1.5px solid var(--v-danger); }
[data-slot="field"], [data-slot="field-group"] { min-width:0; }
[data-slot="field-description"] { overflow-wrap:anywhere; line-height:1.5; }

/* Composition is independent of the control's surface. Existing omissions
   retain the original vertical field; labels remain native and visible. */
[data-slot="field"][data-layout="inline"] { grid-template-columns:minmax(120px,.8fr) minmax(0,1.4fr); gap:8px 24px; align-items:start; }
[data-slot="field"][data-layout="inline"] > [data-slot="field-label"] { grid-column:1; grid-row:1; padding-top:12px; }
[data-slot="field"][data-layout="inline"] > :is(.v-input,.v-igroup,.v-textarea) { grid-column:2; grid-row:1 / span 2; }
[data-slot="field"][data-layout="inline"] > [data-slot="field-description"] { grid-column:1; margin:0; }
[data-slot="field"][data-layout="inline"] > [role="alert"] { grid-column:2; }
[data-slot="field"][data-layout="integrated"] { padding:18px; border-radius:min(var(--v-control-radius,20px),20px); border:1px solid var(--v-border); gap:8px; }
[data-slot="field"][data-layout="integrated"][data-appearance="editorial"] { border:0; border-radius:0; padding-inline:0; }
@media(max-width:560px) {
  [data-slot="field"][data-layout="inline"] { grid-template-columns:minmax(0,1fr); }
  [data-slot="field"][data-layout="inline"] > :is([data-slot="field-label"],.v-input,.v-igroup,.v-textarea,[data-slot="field-description"]) { grid-column:auto; grid-row:auto; padding-top:0; }
}

}

@layer cojeev-states {
/* One inherited corner contract, with a readable cap for multiline/native fields. */
:is(.v-input,.v-igroup,.v-select,.v-native,.v-number-input,.v-btn) {
  border-radius: var(--v-control-radius, var(--r-pill));
}
:is(.v-textarea,.v-composer,.v-native,.v-multi-select__trigger) {
  border-radius: min(var(--v-control-radius, 20px), 20px);
}
.v-btn[data-control-shape="card"] { border-radius: 12px; }
.v-btn[data-control-shape="pill"] { border-radius: var(--r-pill); }

/* A Field can own the treatment for its immediate shell; explicit child paint wins. */
:root .v-native[data-appearance] { padding-inline-end:40px; }
:root .v-native[data-appearance][size]:not([size="1"]) { padding-inline:8px; }
[data-slot="field"][data-appearance="contour"] { --v-field-face: var(--v-canvas); }
:root [data-appearance="contour"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="contour"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-color: var(--v-canvas);
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  border-radius: 0;
  background-color: transparent;
  color: var(--v-text);
  box-shadow: inset 0 -1px 0 var(--v-edge);
  padding-inline: 2px;
}
:root [data-slot="field"][data-appearance="inset"] {
  padding: 14px 16px;
  border-radius: min(var(--v-control-radius, 20px), 20px);
  background: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 9%, transparent);
  gap: 6px;
}
:root [data-appearance="inset"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger) {
  background-color: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 12%, transparent);
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background: transparent;
  box-shadow: none;
  padding-inline: 0;
}
:root [data-slot="field"][data-appearance="inset"] [data-slot="field-label"] { color: var(--v-text-2); }
:root [data-slot="field"][data-appearance="inset"]:focus-within { outline: 2px solid var(--v-brand); outline-offset: 2px; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):focus-within,
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):focus-within {
  outline: 2px solid var(--v-brand);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):focus-within { outline: none; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is(:disabled,[data-disabled="true"],:has(input:disabled)),
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):is(:disabled,:has(input:disabled)) {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  cursor: not-allowed;
}
:root [data-slot="field"][data-appearance][data-state="error"],
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is([aria-invalid="true"],[data-invalid="true"],:has([aria-invalid="true"])) {
  outline: 2px solid var(--v-danger-fill);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance][data-state="error"] [role="alert"] { color: var(--v-danger-ink); }

.v-form-example { display: grid; gap: 20px; width: 100%; min-width: 0; max-width: 480px; margin-inline: auto; }
.v-form-example__intro { display: grid; gap: 5px; }
.v-form-example__intro strong { font-family: var(--font-display, inherit); font-size: 22px; font-weight: 500; }
.v-form-example__intro p { margin: 0; color: var(--v-text-2); font-size: 13px; line-height: 1.5; }
.v-form-example__status { min-height: 1.5em; margin: 0; font-size: 12px; color: var(--v-text-2); overflow-wrap: anywhere; }
.v-form-example__footer { display: flex; gap: 10px; align-items: center; justify-content: space-between; }

/* Composer owns one surface, while the actual textarea keeps native editing. */
:root .v-composer[data-appearance] { border-radius:min(var(--v-control-radius,20px),20px); background:var(--v-canvas); color:var(--v-text); box-shadow:inset 0 0 0 1px var(--v-edge); }
:root .v-composer[data-appearance="inset"] { background:var(--v-beige); box-shadow:inset 0 1px 2px color-mix(in oklab,var(--v-text) 12%,transparent); }
:root .v-composer[data-appearance="editorial"] { border-radius:0; background:transparent; box-shadow:inset 0 -1px 0 var(--v-edge); }
:root .v-composer[data-appearance] .v-textarea:is(:focus,:hover,:not(:focus)) { background:transparent; box-shadow:none; outline:0; border-radius:0; resize:vertical; }
:root .v-composer[data-appearance] .v-textarea-scroll > textarea { padding-inline-end:30px; }
:root [data-slot="field"][data-appearance] [data-slot="input-group"] .v-textarea { background:transparent; box-shadow:none; outline:0; border:0; border-radius:0; }
:root .v-composer[data-appearance]:focus-within { outline:2px solid var(--v-brand); outline-offset:3px; }
:root [data-slot="field"][data-appearance="inset"] .v-composer[data-appearance] { background:transparent; box-shadow:none; outline:0; }
.v-form-example[data-form-example="field"] { max-width:600px; }
.v-form-example [data-slot="field-label"] { font-size:14px; line-height:1.5; }
.v-form-example [data-slot="field-description"] { font-size:13px; margin:0; }
.v-form-example__footer > .v-btn, .v-form-example [data-slot="textarea-composer-bar"] > .v-btn { min-height:44px; }
.v-form-example [data-slot="textarea-composer-bar"] { justify-content:space-between; flex-wrap:wrap; gap:12px; padding:10px 12px; border-top:1px solid var(--v-border); }
.v-form-example__allowance { height:4px; border-radius:4px; overflow:hidden; background:var(--v-beige); margin-top:-8px; }
.v-form-example__allowance > span { display:block; height:100%; max-width:100%; border-radius:inherit; background:var(--v-blue-deep); }
.v-form-example__label-row { display:flex; align-items:baseline; flex-wrap:wrap; gap:8px; justify-content:space-between; }
.v-form-example__label-row > span { font-size:12px; color:var(--v-text-2); }
.v-form-example__hint { margin:0; color:var(--v-text-2); font-size:13px; line-height:1.5; }
/* Editorial draws only the focus edge: no moving caret, label or hit area. */
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-image:linear-gradient(var(--v-brand),var(--v-brand)); background-repeat:no-repeat; background-position:left bottom; background-size:0% 2px;
  transition:background-size var(--t-micro) var(--enter);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer):focus-within,
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):focus-within { background-size:100% 2px; outline:0; }
@media(prefers-reduced-motion:reduce) { :root [data-slot="field"] :is(.v-input,.v-igroup,.v-textarea,.v-composer) { transition:none; } }

}
